
if (window.innerWidth < 768) {
	[].slice.call(document.querySelectorAll('[data-bss-disabled-mobile]')).forEach(function (elem) {
		elem.classList.remove('animated');
		elem.removeAttribute('data-bss-hover-animate');
		elem.removeAttribute('data-aos');
		elem.removeAttribute('data-bss-parallax-bg');
		elem.removeAttribute('data-bss-scroll-zoom');
	});
}

document.addEventListener('DOMContentLoaded', function() {

	var hoverAnimationTriggerList = [].slice.call(document.querySelectorAll('[data-bss-hover-animate]'));
	var hoverAnimationList = hoverAnimationTriggerList.forEach(function (hoverAnimationEl) {
		hoverAnimationEl.addEventListener('mouseenter', function(e){ e.target.classList.add('animated', e.target.dataset.bssHoverAnimate) });
		hoverAnimationEl.addEventListener('mouseleave', function(e){ e.target.classList.remove('animated', e.target.dataset.bssHoverAnimate) });
	});
}, false);
document.addEventListener("DOMContentLoaded", function() {
    
    // 1. The Target Containers
    const targets = document.querySelectorAll(`
        .sando-hero,
        .bio-text-container, .sando-flyer, .track-stack,
        .transport-deck, #track-grid,
        .previews-header, .lexan-deck, .daw-window,
        .tactical-item, .desk-stamp,
        .premium-header, .premium-subtext, .premium-glass-card
    `);

    // 2. The Observer Brain
    const observer = new IntersectionObserver((entries) => {
        const visibleEntries = entries.filter(entry => entry.isIntersecting);

        visibleEntries.forEach((entry, index) => {
            
            setTimeout(() => {
                // Trigger the fade-in
                entry.target.classList.add('sando-reveal');

                // 1.2s later: lock opacity at 1, but unlock transforms for your hovers
                setTimeout(() => {
                    entry.target.classList.remove('sando-reveal');
                    entry.target.classList.add('animation-complete');
                }, 1200); 

            }, index * 150); 

            observer.unobserve(entry.target);
        });
    }, { 
        threshold: 0.1 
    });

    // 3. Start watching
    setTimeout(() => {
        targets.forEach(el => observer.observe(el));
    }, 50); 
});
document.addEventListener("DOMContentLoaded", function() {
    const video = document.getElementById("bio-teaser-video");
    const playBtn = document.getElementById("video-play-toggle");
    const muteBtn = document.getElementById("video-mute-toggle");

    if (video && playBtn && muteBtn) {
        
        /* Play/Pause Button Logic */
        playBtn.addEventListener("click", function() {
            if (video.paused) {
                video.play();
                playBtn.textContent = "PAUSE";
                playBtn.classList.remove("is-active");
            } else {
                video.pause();
                playBtn.textContent = "PLAY";
                playBtn.classList.add("is-active");
            }
        });

        /* Mute/Unmute Button Logic */
        muteBtn.addEventListener("click", function() {
            if (video.muted) {
                video.muted = false;
                muteBtn.textContent = "MUTE";
                muteBtn.classList.remove("is-active");
            } else {
                video.muted = true;
                muteBtn.textContent = "UNMUTE";
                muteBtn.classList.add("is-active");
            }
        });
        
    }
});
document.addEventListener('DOMContentLoaded', () => {
    const holdButtons = document.querySelectorAll('.hold-to-submit-btn');

    // THE FIX: If there are no hold buttons on this page, stop instantly.
    if (holdButtons.length === 0) return;

    holdButtons.forEach(btn => {
        const form = btn.closest('form');
        const btnText = btn.querySelector('.btn-text');
        let holdTimer;
        
        // Capture the original text ("Hold to Subscribe" or "Hold to Submit")
        const originalText = btnText ? btnText.textContent : "Submit";

        // Prevent mobile context menu on long press
        btn.addEventListener('contextmenu', e => e.preventDefault());

        const startHold = (e) => {
            if (btn.classList.contains('is-confirmed')) return;
            
            // 1. Native form validation
            if (form && !form.checkValidity()) {
                form.reportValidity(); 
                return;
            }

            // Only prevent default on mobile touch to avoid disrupting desktop clicks
            if (e.type === 'touchstart' && e.cancelable) e.preventDefault();

            // 2. Start CSS purple fill animation
            btn.classList.add('is-holding');

            // 3. The 1.5s Hold Timer
            holdTimer = setTimeout(() => {
                
                // Snap to Green / Confirmed State
                btn.classList.remove('is-holding');
                btn.classList.add('is-confirmed');
                if(btnText) btnText.textContent = "Message Sent";
                btn.style.pointerEvents = "none"; // Lock the button

                // Trigger standard HTML submission (This goes to the hidden iframe)
                if (form) {
                    form.submit();
                    // Clear the text boxes 0.5s later so it looks clean
                    setTimeout(() => form.reset(), 500); 
                }

                // 4. THE RESET (Wait 3.5 seconds, then go back to normal)
                setTimeout(() => {
                    btn.classList.remove('is-confirmed');
                    if(btnText) btnText.textContent = originalText;
                    btn.style.pointerEvents = ""; // Unlock the button
                }, 3500);
                
            }, 1500); 
        };

        const cancelHold = () => {
            if (btn.classList.contains('is-confirmed')) return;
            clearTimeout(holdTimer);
            btn.classList.remove('is-holding'); // Drains the purple bar
        };

        btn.addEventListener('mousedown', startHold);
        btn.addEventListener('mouseup', cancelHold);
        btn.addEventListener('mouseleave', cancelHold);
        btn.addEventListener('touchstart', startHold, { passive: false });
        btn.addEventListener('touchend', cancelHold);
        btn.addEventListener('touchcancel', cancelHold);
    });
});

