// ========================================= 
// 2. THE ENGINE
// ========================================= 
const trackGrid = document.getElementById('track-grid');
const filterButtons = document.querySelectorAll('.transport-btn');

function renderReel(filterType) {
    // ESCAPE HATCH 1: Stop immediately if this page doesn't have a track grid
    if (!trackGrid) return; 

    trackGrid.innerHTML = '';

    let filteredTracks = releases;
    
    if (filterType === 'greatest') {
        filteredTracks = releases.filter(track => track.greatest === true);
    } else if (filterType !== 'all') {
        filteredTracks = releases.filter(track => track.genre === filterType);
    }

    filteredTracks.forEach((release) => {
        const randomTilt = (Math.random() * 4 - 2).toFixed(1);

        trackGrid.innerHTML += `
            <div class="frame-wrapper">
                <a href="${release.url}" target="_blank" class="film-frame" style="transform: translateY(0px) rotate(${randomTilt}deg);">
                    <div class="peg"></div>
                    <div class="sprocket-holes"></div>
                    <div class="frame-content">
                        <img src="https://cdn.jsdelivr.net/gh/SandoProduces/sandowebsiteassets@main/${release.art}" alt="${release.title}">
                        <div class="hover-glow"></div>
                    </div>
                    <div class="sprocket-holes"></div>
                    <div class="margin-notes">
                        <p class="release-title">${release.title}</p>
                        <p class="release-info">${release.label} | ${release.year}</p>
                        <span class="handwritten-note">${release.note}</span>
                    </div>
                </a>
            </div>
        `;
    });
}

// ========================================= 
// 3. THE TAPE DECK CONTROLS
// ========================================= 
filterButtons.forEach(button => {
    button.addEventListener('click', () => {
        if(button.classList.contains('active')) return;

        filterButtons.forEach(btn => btn.classList.remove('active'));
        button.classList.add('active');

        // ESCAPE HATCH 2: Only apply visual filters if the grid actually exists
        if (trackGrid) {
            trackGrid.style.transition = "all 0.2s ease";
            trackGrid.style.filter = "blur(12px)";
            trackGrid.style.transform = "translateX(-30px)";

            setTimeout(() => {
                const filterValue = button.getAttribute('data-filter');
                renderReel(filterValue);
                
                trackGrid.style.filter = "blur(0px)";
                trackGrid.style.transform = "translateX(0px)";
            }, 200);
        }
    });
});

// ESCAPE HATCH 3: Only trigger the initial load if we are actually on the Discography page
if (trackGrid) {
    renderReel('greatest');
}
